static av_always_inline av_const long int lrintf(float x) /* <=== lrintf */ 
{
    return (int)(rint(x));
}

static inline double rint(double x) /* <=== rint */ 
{
    return x >= 0 ? floor(x + 0.5) : ceil(x - 0.5);
}

static av_always_inline av_const int av_clip_c(int a, int amin, int amax) /* <=== av_clip_c */ 
{
#if defined(HAVE_AV_CONFIG_H) && defined(ASSERT_LEVEL) && ASSERT_LEVEL >= 2
    if (amin > amax) abort();
#endif
    if      (a < amin) return amin;
    else if (a > amax) return amax;
    else               return a;
}

